'use strict';
/* YLSY Atlas 2.4.3 — original local-first UI. No tracker, CDN, account or remote API. */
const TOKEN=new URL(location.href).searchParams.get('token')||'';
const state={nav:'dashboard',guide:0,guideList:[],templates:[],overview:null,settings:{},cache:{},filter:'all',selectedUniversity:null,selectedAdvisor:null,searchText:'',monthOffset:0,docId:null,docTimer:null,mobile:false,guidePdf:{available:false},vocabSort:'newest',vocabQuiz:null,ieltsSkill:'all',ieltsPeriod:'all',ieltsSort:'newest',dictionaryTimer:null};let eventsBound=false;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;const icon=(id,size=18)=>`<svg aria-hidden="true" width="${size}" height="${size}"><use href="#i-${id}"/></svg>`;
const labelText=s=>String(s||'').trim();
const TASK_STATUS_LABELS={todo:'Yapılacak',doing:'Devam ediyor',done:'Tamamlandı'};
const statusLabel=s=>TASK_STATUS_LABELS[s]||s;
function truncate(s,n=120){s=String(s??'');return s.length>n?s.slice(0,n-1)+'…':s}
function fmtDate(v){if(!v)return 'Belirlenmedi';const t=String(v).slice(0,10).split('-');return t.length===3?`${t[2]}.${t[1]}.${t[0]}`:v}
function pill(s){let v=String(s||'');let type=/Kabul|Tamam|done|Doğrulandı|Olumlu/i.test(v)?'success':/Ret|Vazgeçildi|Gecik|Reddedildi/i.test(v)?'danger':/Doğrulanmadı|Bekleme|Hazırlanıyor|yapılacak/i.test(v)?'warn':'';return `<span class="pill ${type}">${esc(statusLabel(v||'Belirlenmedi'))}</span>`}
function link(url,text='Bağlantı'){if(!url)return '';try{let x=new URL(url);if(!['https:','http:'].includes(x.protocol))return '';return `<a href="${attr(x.href)}" target="_blank" rel="noopener noreferrer">${esc(text)} ${icon('external',13)}</a>`}catch{return ''}}
function pdfUrl(page=1){return `/pdf?token=${encodeURIComponent(TOKEN)}#page=${Math.max(1,Number(page)||1)}&view=FitH`}
function btn(label,act,iconName,kind=''){return `<button class="btn ${kind}" data-act="${attr(act)}">${icon(iconName)} ${esc(label)}</button>`}
function heading(kicker,title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`}
function empty(title,sub,act='',name='Yeni kayıt ekle'){return `<div class="empty">${icon('sparkle',32)}<strong>${esc(title)}</strong><p>${esc(sub)}</p>${act?btn(name,act,'plus','btn-primary'):''}</div>`}
function card(title,body,actions='',subtitle=''){return `<div class="card card-pad"><div class="card-heading"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${actions}</div>${body}</div>`}
function metric(label,value,foot,ic,action=''){return `<${action?'button':'div'} class="metric metric-premium" ${action?`data-act="${attr(action)}"`:''}><span class="metric-icon">${icon(ic,22)}</span><span class="metric-copy"><span class="metric-label">${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(foot)}</small></span></${action?'button':'div'}>`}

const dateLong=()=>new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric',weekday:'long'}).format(new Date());
const daysTo=(v)=>{if(!v)return null;const due=new Date(String(v).slice(0,10)+'T12:00:00');const now=new Date();now.setHours(12,0,0,0);return Math.ceil((due-now)/86400000)};
function titleBand(section,title,subtitle,actions=''){return `<div class="title-band"><div class="title-left"><span class="eyebrow">${esc(section)}</span><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${actions?`<div class="title-actions">${actions}</div>`:''}</div>`}
function blockHeading(title,ic,action=''){return `<div class="block-heading"><h2>${icon(ic,21)} ${esc(title)}</h2>${action}</div>`}
function actionTile(name,ic,action){return `<button class="action-tile" data-act="${attr(action)}">${icon(ic,25)}<span>${esc(name)}</span></button>`}
function stageStatFor(guideEntry){const ts=(state.cache.tasks||[]).filter(x=>x.guide_key===guideEntry.id);const complete=ts.length&&ts.every(x=>x.status==='done');return `<span class="stage-status ${complete?'stage-complete':ts.length?'stage-started':'stage-none'}">${complete?'Tamamlandı':ts.length?'Devam ediyor':'Başlanmadı'}</span>`}
function updateFilteredList(input){const root=input.closest('.list-with-filter');if(!root)return;const needle=input.value.toLocaleLowerCase('tr-TR').trim();root.querySelectorAll('[data-match]').forEach(el=>{el.hidden=!el.dataset.match.toLocaleLowerCase('tr-TR').includes(needle)})}

function toast(msg,error=false){let d=document.createElement('div');d.className='toast'+(error?' error':'');d.textContent=msg;$('#toast-container').append(d);setTimeout(()=>d.remove(),4100)}
function byId(table,id){return (state.cache[table]||[]).find(x=>+x.id===+id)}
async function api(endpoint,method='GET',data){const opt={method,headers:{'X-Atlas-Token':TOKEN}};if(data!==undefined){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(data)}const response=await fetch(`/api/${endpoint}`,opt);if(!response.ok){let msg;try{msg=(await response.json()).error}catch{msg=response.statusText}throw new Error(msg||'İşlem başarısız')}return endpoint==='backup'||endpoint.endsWith('.docx')?response.blob():response.json()}
async function reload(tables=[]){const all=[...new Set(tables)];const pairs=await Promise.all(all.map(async t=>[t,await api(t)]));for(const [t,d]of pairs)state.cache[t]=d;state.overview=await api('overview')}
async function start(){try{[state.guideList,state.templates,state.settings,state.guidePdf]=await Promise.all([api('guide'),api('templates'),api('settings'),api('guide-pdf/status')]);await reload(['universities','programs','advisors','tasks','documents','ielts_sessions','vocabulary','events','attachments','notes','resources']);wire();document.body.classList.toggle('sidebar-collapsed',state.settings.sidebar_collapsed==='true');render()}catch(e){$('#main').innerHTML=`${empty('Uygulama yüklenemedi',e.message)}<div style="text-align:center">${btn('Yeniden dene','retry','right','btn-primary')}</div>`;wire();toast(e.message,true)}}
const names={dashboard:'Kontrol Paneli',roadmap:'Yol Haritası',guide:'MEB Başvuru Rehberi',universities:'Üniversiteler',advisors:'Danışmanlar',applications:'Başvurular',documents:'Belge Stüdyosu',ielts:'İngilizce & IELTS',vocabulary:'Kelime Defterim',administration:'YLSY ve Pasaport',calendar:'Takvim ve Hatırlatmalar',files:'Dosya Kasası',notes:'Notlar',resources:'Kaynaklar & Yayınlar',settings:'Ayarlar & Yedekleme'};
async function nav(page,fromPop=false){if(!(page in names))return;if(state.nav==='documents'&&$('#doc-editor')){clearTimeout(state.docTimer);await saveDocument()}clearTimeout(state.docTimer);state.nav=page;state.filter='all';state.mobile=false;document.body.classList.remove('mobile-open');if(!fromPop&&history.state?.atlasPage!==page)history.pushState({atlasPage:page},'','#'+page);render();$('#main').scrollTop=0}
function render(){const p=state.nav;$('#main').innerHTML=`<div class="page">${({dashboard,roadmap,guide:guideView,universities,advisors,applications,documents,ielts,vocabulary,administration,calendar,files,notes,resources,settings})[p]()}</div>`;document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('is-active',b.dataset.nav===p));$('#breadcrumbs').innerHTML=`<span>YLSY ATLAS</span>${icon('chevron')}<b>${esc(names[p])}</b>`;}
function dashboard(){
 const o=state.overview||{}, tasks=state.cache.tasks||[], dates=upcoming().filter(x=>x.date >= new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+'-'+String(new Date().getDate()).padStart(2,'0')).slice(0,3);
 const pending=tasks.filter(x=>x.status!=='done').slice(0,4);
 const nDone=o.done||0, pct=o.total?o.completion:0;
 const focus=(state.settings.research_focus||'').trim(), tags=(state.settings.research_tags||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,6);
 const suggestions=[
   {title:'Hedef üniversite listeni oluştur',act:'add-university',ic:'school'},
   {title:'IELTS hedefini ve çalışma planını belirle',act:'goto-ielts',ic:'language'},
   {title:'MEB rehberindeki aşamaları gözden geçir',act:'open-roadmap',ic:'book'},
   {title:'Akademik CV taslağına başla',act:'choose-template',ic:'file'}
 ];
 const suggestionsHtml = pending.length ? pending.map(x=>`<div class="recommendation-item"><button class="check-box ${x.status==='done'?'done':''}" data-act="toggle-task" data-id="${x.id}" title="Görevi tamamla">${icon('check',14)}</button><span class="recommendation-label">${esc(x.title)}</span><button class="row-chevron" data-edit="tasks" data-id="${x.id}" title="Görevi düzenle">${icon('right',16)}</button></div>`).join('') : suggestions.map(x=>`<button class="recommendation-item" data-act="${x.act}"><span class="recommendation-check">${icon('check',12)}</span><span class="recommendation-label">${esc(x.title)}</span>${icon('right',16)}</button>`).join('');
 const dateHtml=dates.length?dates.map(x=>`<div class="date-compact"><span class="date-compact-label">${icon('calendar',17)} <strong>${fmtDate(x.date)}</strong></span><span class="date-compact-title">${esc(x.title)}</span><span class="date-compact-days">${Math.max(0,daysTo(x.date)||0)} gün kaldı</span></div>`).join(''):`<div class="date-compact date-compact-empty"><span>${icon('info',18)} Henüz takip ettiğin bir tarih yok.</span><button class="btn btn-primary" data-act="add-event">${icon('plus',15)} Tarih Ekle</button></div>`;
 const focusTags=tags.length?tags.map(t=>`<span class="tag-pill">${esc(t)}</span>`).join(''):'<span class="focus-hint">Araştırma alanını ve anahtar kelimelerini tanımlayabilirsin.</span>';
 return `<div class="atlas-dashboard">
   ${titleBand('YLSY BURSİYERLERİ İÇİN BAŞVURU YÖNETİMİ','Başvuru Kontrol Paneli','YLSY başvuru sürecini planla, ilerlemeni takip et ve hazırlıklarını tek yerden yönet.',`<div class="date-badge">${icon('calendar',22)} <span>${dateLong()}</span></div>`)}
   <div class="metrics-5">${metric('Üniversite',o.university_count||0,'Üniversite ekle','school','add-university')}${metric('Başvuru',o.submitted||0,'Başvuru oluştur','file','goto-applications')}${metric('Kabul',o.accepted||0,'Kabul kaydı ekle','check','goto-applications')}${metric('Görev',`${nDone} / ${o.total||0}`,'Görev planına git','task','open-roadmap')}${metric('Genel ilerleme',`%${pct}`,'İlerlemeni görüntüle','chart','open-roadmap')}</div>
   <div class="dashboard-grid">
     <section class="premium-panel road-progress">${blockHeading('Başvuru Yol Haritası (MEB Rehberi)','file')}<div class="progress-body"><div class="ring-progress" style="--p:${pct}"><span>%${pct}</span></div><div class="progress-copy"><div class="stage-label">Aşama: <span class="stage-chip">${o.total?'Devam ediyor':'Başlangıç'}</span></div><p>${o.total?`${nDone} / ${o.total} görevi tamamladın.`:'Henüz kişisel takip görevi oluşturmadın.'}</p><button class="btn btn-primary" data-act="open-roadmap">${icon('right',16)} Yol Haritasına Git</button></div></div><div class="subtle-wave"></div></section>
     <section class="premium-panel upcoming-panel">${blockHeading('Yaklaşan Tarihler','calendar',`<button data-nav="calendar" class="text-action">Tümünü Gör ${icon('right',14)}</button>`)}<div class="compact-dates">${dateHtml}</div></section>
     <section class="premium-panel quick-panel">${blockHeading('Hızlı Erişim','route')}<div class="quick-grid">${actionTile('Üniversite Ekle','school','add-university')}${actionTile('Danışman Ekle','users','add-advisor')}${actionTile('Görev Ekle','task','add-task')}${actionTile('Belge Oluştur','file','choose-template')}${actionTile('IELTS Takibi','language','goto-ielts')}${actionTile('MEB Rehberi','book','open-guide')}${actionTile('REBUS’a Git','external','open-rebus')}${actionTile('Takvim','calendar','goto-calendar')}</div></section>
     <section class="premium-panel recommended-panel">${blockHeading(pending.length?'Öncelikli Görevlerin':'Bugünün Önerileri','sparkle',`<button data-nav="roadmap" class="text-action">${pending.length?'Tüm Görevler': 'Yol Haritası'} ${icon('right',14)}</button>`)}<div class="recommendation-list">${suggestionsHtml}</div></section>
   </div>
   <div class="focus-banner"><div class="focus-visual" aria-hidden="true"></div><div class="focus-copy"><span class="focus-kicker">Araştırma Odak Alanın</span><h3>${esc(focus||'Araştırma odağını belirle')}</h3><div class="focus-tags">${focusTags}</div></div><button data-act="set-focus" class="btn focus-edit">${icon('edit',17)} ${focus?'Alanı Düzenle':'Alan Ekle'}</button></div>
 </div>`;
}
function roadmap(){
 const guide=state.guideList||[],g=guide[state.guide]||guide[0],tasks=state.cache.tasks||[],linked=tasks.filter(t=>t.guide_key===g?.id);const complete=tasks.filter(t=>t.status==='done').length;
 return `${titleBand('MEB REHBERİ · AŞAMALI İLERLEME','Başvuru Yol Haritası','Resmî rehberin bütün bölüm ve eklerini incele; ihtiyaç duyduğun görevleri oluştur.',btn('Yeni görev oluştur','add-task','plus','btn-primary'))}
 <div class="road-strip"><div><span>Rehber</span><strong>${guide.length} bölüm ve ek</strong></div><div><span>Kişisel görevler</span><strong>${complete} / ${tasks.length} tamamlandı</strong></div><div class="road-progressbar"><span>Gerçek görev ilerlemesi</span><div class="progress"><i style="width:${tasks.length?(complete/tasks.length*100):0}%"></i></div></div></div>
 <div class="road-layout"><section class="premium-panel roadmap-list">${blockHeading('MEB Rehberi Başvuru Aşamaları','book')}<div class="road-entries">${guide.map((x,i)=>{const n=tasks.filter(t=>t.guide_key===x.id).length;return `<button class="road-entry ${i===state.guide?'selected':''}" style="--depth:${x.level}" data-act="guide-select" data-index="${i}"><span class="road-mark">${icon(x.level?'chevron':'book',15)}</span><span class="road-name"><b>${esc(x.id)} · ${esc(x.title)}</b><small>${n} görev · PDF sayfa ${x.page}</small></span>${stageStatFor(x)}</button>`}).join('')}</div></section>
 <section class="road-right"><div class="premium-panel">${blockHeading('Seçili Aşama','route')}<div class="detail-kicker">${esc(g?.id||'')} · PDF SAYFA ${g?.page||''}</div><h2 class="detail-title">${esc(g?.title||'')}</h2><p class="detail-body">${esc(g?.summary||'')}</p><div class="detail-actions">${btn('Görev oluştur','guide-task','plus','btn-primary')}${btn('Kaynak sayfasını aç','pdf-new','book')}</div><div class="section-divider"></div><h3 class="subsection-heading">Bu aşamadaki görevler</h3>${linked.length?linked.map(taskRow).join(''):empty('Henüz görev oluşturulmadı','Bu rehber aşamasına bağlı bir görev ekleyebilirsin.','guide-task','Görev ekle')}</div><div class="premium-panel source-panel">${blockHeading('Kaynak ve açıklama','info')}<p>Bu başlık, uygulamada bulunan MEB ABD lisansüstü başvuru rehberiyle ilişkilidir. Güncel mevzuat ve üniversite şartlarını ayrıca resmî kaynaklardan doğrula.</p>${btn('PDF sayfasını görüntüle','pdf-new','external')}</div></section></div>`
}
function taskRow(x){return `<div class="task-row"><button class="check-box ${x.status==='done'?'done':''}" data-act="toggle-task" data-id="${x.id}" title="Tamamlandı durumunu değiştir">${icon('check')}</button><div class="task-row-content ${x.status==='done'?'completed':''}"><b>${esc(x.title)}</b><p>${esc([x.track,x.group_name,x.due_date?fmtDate(x.due_date):''].filter(Boolean).join(' · '))}</p><div class="task-meta">${pill(x.status==='done'?'Tamamlandı':x.status==='doing'?'Devam ediyor':'Yapılacak')}${x.source_page?`<button data-act="pdf-page" data-page="${x.source_page}" class="inline-link">PDF s. ${x.source_page}</button>`:''}</div></div><div class="list-row-actions"><button class="round-btn" title="Düzenle" data-edit="tasks" data-id="${x.id}">${icon('edit')}</button><button class="round-btn" title="Sil" data-delete="tasks" data-id="${x.id}">${icon('trash')}</button></div></div>`}
function guideView(){let x=state.guideList[state.guide]||state.guideList[0],guideTasks=(state.cache.tasks||[]).filter(t=>t.guide_key===x.id);let related=state.templates.filter(t=>t.ref_key===x.id);return `${heading('MEB / 1416 / ABD','Başvuru Rehberi','Rehberin bütün başlıkları ve EK 1–8 PDF içindeki gerçek sayfalarına bağlıdır.',`${btn('PDF Seç / Değiştir','guide-pdf-import','upload','btn-primary')}${state.guidePdf?.available?btn('PDF’yi aç','pdf-new','external'):''}`)}
<div class="guide-layout"><div class="card guide-tree">${state.guideList.map((g,i)=>`<button class="guide-entry ${i===state.guide?'active':''}" data-act="guide-select" data-index="${i}" data-level="${g.level}"><strong>${esc(g.id)} · ${esc(g.title)}</strong><small>${g.page}</small></button>`).join('')}</div><div class="card guide-preview"><div class="guide-summary"><div class="eyebrow">REHBER / ${esc(x.id)} · PDF SAYFA ${x.page}</div><h2>${esc(x.title)}</h2><p>${esc(x.summary)}</p><div class="head-actions">${btn('Bu aşama için görev oluştur','guide-task','plus','btn-primary')}${btn('Sayfayı aç','pdf-new','external')}${related.length?btn('Örnek belge taslağı','template-this','file'):''}</div>${guideTasks.length?`<div class="margin-top"><small class="subtle">BU AŞAMAYLA İLİŞKİLİ GÖREVLER</small>${guideTasks.map(taskRow).join('')}</div>`:''}<div class="helper-note" style="margin-top:18px">Bu belge başvuru yol haritasıdır. Üniversite ve YLSY koşullarının güncel geçerliliği resmî kaynaklardan ayrıca doğrulanmalıdır.</div></div>${state.guidePdf?.available?`<iframe class="pdf-frame" title="MEB ABD başvuru rehberi" loading="lazy" src="${pdfUrl(x.page)}"></iframe>`:`<section class="pdf-missing"><div class="pdf-missing-icon">${icon('book',35)}</div><h3>MEB rehberi henüz eklenmedi</h3><p>PDF dosyasını adını değiştirmeden bilgisayarından seçebilirsin. Uygulama onu kendi yerel veri klasörüne kaydeder; daha sonra tekrar seçmen gerekmez.</p><button class="btn btn-primary" data-act="guide-pdf-import">${icon('upload')} PDF Seç</button><small>Beklenen içerik: 1416’lı Bursiyerler Lisansüstü Eğitim Başvuru Rehberi (ABD) · en fazla 40 MB</small></section>`}</div></div>`}
function universities(){const u=state.cache.universities||[],p=state.cache.programs||[],a=state.cache.advisors||[];
 if(!u.some(x=>Number(x.id)===Number(state.selectedUniversity)))state.selectedUniversity=u[0]?.id||null;
 const selected=byId('universities',state.selectedUniversity),ps=p.filter(x=>Number(x.university_id)===Number(selected?.id)),as=a.filter(x=>Number(x.university_id)===Number(selected?.id));
 return `${titleBand('AKADEMİK KURUMLAR','Üniversiteler ve Programlar','Üniversiteleri, doktora programlarını ve güncel başvuru şartlarını birlikte yönet.',btn('Üniversite ekle','add-university','plus','btn-primary'))}
 <div class="metrics-4">${metric('Toplam üniversite',u.length,'Kurum kayıtları','school')}${metric('Doktora programı',p.length,'Program seçenekleri','book')}${metric('Danışman',a.length,'İlişkili akademisyenler','users')}${metric('Yaklaşan tarih',p.filter(x=>x.deadline&&daysTo(x.deadline)>=0&&daysTo(x.deadline)<=30).length,'30 gün içinde','calendar')}</div>
 ${!u.length?`<section class="premium-panel first-empty">${empty('Henüz üniversite eklenmedi','İlk üniversiteni ekleyerek programları, danışmanları ve son tarihleri ilişkilendirebilirsin.','add-university','İlk üniversiteyi ekle')}</section>`:`<div class="split-layout"><section class="premium-panel list-with-filter"><div class="filter-line">${icon('search')} <input aria-label="Üniversitelerde ara" class="inline-search" placeholder="Üniversite, ülke veya şehir ara..." data-live-filter/></div><div class="university-list">${u.map(x=>`<button class="uni-row ${Number(x.id)===Number(state.selectedUniversity)?'selected':''}" data-act="select-university" data-id="${x.id}" data-match="${attr([x.name,x.short,x.city,x.country].join(' '))}"><span class="uni-glyph">${icon('school',23)}</span><span class="uni-info"><strong>${esc(x.short||x.name)}</strong><small>${esc(x.name)}</small><small>${esc(x.city||'Şehir belirtilmedi')} · ${esc(x.country||'Ülke belirtilmedi')}</small></span><span class="uni-row-extra">${pill(x.ylsy_status)}${icon('right')}</span></button>`).join('')}</div></section><section class="premium-panel uni-detail">${blockHeading(selected?.short||selected?.name,'school',`<button class="btn btn-small" data-edit="universities" data-id="${selected.id}">${icon('edit')} Düzenle</button>`)}<p class="detail-body">${esc(selected?.name||'')} · ${esc([selected?.city,selected?.country].filter(Boolean).join(', '))}</p><div class="detail-flag-row">${pill(selected?.ylsy_status)}<span class="pill">${ps.length} program</span><span class="pill">${as.length} danışman</span></div>${selected?.note?`<div class="helper-note">${esc(selected.note)}</div>`:''}<div class="section-divider"></div><div class="flex-title"><h3>Doktora programları</h3><button class="text-action" data-act="add-program">${icon('plus',14)} Program ekle</button></div>${ps.length?ps.map(x=>`<div class="related-item"><div><b>${esc(x.name)}</b><small>${esc(x.laboratory||'Laboratuvar girilmedi')} · Son tarih: ${fmtDate(x.deadline)}</small><small>${x.deadline_verified?'Tarih doğrulandı':'Tarih henüz doğrulanmadı'}</small></div><button class="round-btn" data-edit="programs" data-id="${x.id}">${icon('edit')}</button></div>`).join(''):'<p class="muted">Bu üniversite için henüz doktora programı kaydedilmedi.</p>'}<div class="section-divider"></div><div class="flex-title"><h3>Danışmanlar</h3><button class="text-action" data-act="add-advisor">${icon('plus',14)} Danışman ekle</button></div>${as.length?as.map(x=>`<div class="related-item"><div><b>${esc(x.name)}</b><small>${esc(truncate(x.topic,100))}</small></div>${pill(x.status)}</div>`).join(''):'<p class="muted">Bu üniversiteye bağlı danışman bulunmuyor.</p>'}<div class="detail-actions margin-top">${link(selected?.url,'Üniversitenin resmî sitesi')}<button class="btn btn-danger" data-delete="universities" data-id="${selected.id}">${icon('trash')} Kaydı sil</button></div></section></div>`}`;
}
function universityDetail(id){let s=byId('universities',id),ps=(state.cache.programs||[]).filter(x=>Number(x.university_id)===Number(id)),as=(state.cache.advisors||[]).filter(x=>Number(x.university_id)===Number(id));if(!s)return;state.detailId=id;$('#main').innerHTML=`<div class="page">${heading('Üniversite kaydı',s.name,`${s.city||''} ${s.country||''}`,`${btn('Geri','back-universities','left')}${btn('Program ekle','add-program','plus','btn-primary')}`)}<div class="grid3">${metric('Programlar',ps.length,'Doktora seçenekleri','book')}${metric('Danışmanlar',as.length,'Potansiyel hocalar','users')}${metric('YLSY durumu',s.ylsy_status||'Doğrulanmadı','Resmî teyit gerekli','flag')}</div><div class="panel-grid"><div>${card('Programlar',ps.length?ps.map(z=>`<div class="list-row"><div class="list-icon">${icon('book')}</div><div class="list-row-main"><strong>${esc(z.name)}</strong><small>${esc(z.laboratory||'Laboratuvar belirtilmedi')} · ${fmtDate(z.deadline)} ${z.deadline_verified?'(doğrulandı)':'(teyit edilmedi)'}</small>${pill(z.stage)}</div><div class="list-row-actions"><button class="round-btn" data-edit="programs" data-id="${z.id}">${icon('edit')}</button><button class="round-btn" data-delete="programs" data-id="${z.id}">${icon('trash')}</button></div></div>`).join(''):empty('Program eklenmemiş','İlgili doktora programını ve başvuru tarihini kaydet.','add-program','Program ekle'),btn('Program ekle','add-program','plus'))}</div><div>${card('Danışmanlar',as.length?as.map(z=>`<div class="list-row"><div class="list-icon">${icon('users')}</div><div class="list-row-main"><strong>${esc(z.name)}</strong><small>${esc(z.topic)}</small>${pill(z.status)}</div><div class="list-row-actions"><button class="round-btn" data-edit="advisors" data-id="${z.id}">${icon('edit')}</button></div></div>`).join(''):empty('Danışman eklenmemiş','Potansiyel öğretim üyelerini kaydet.','add-advisor','Danışman ekle'),btn('Danışman ekle','add-advisor','plus'))}</div></div></div>`}
