function previewTemplate(i){const t=state.templates[i];if(!t)return;modal('Şablon ön izlemesi — '+t.title,`<div class="helper-note">Bu şablon düzenlenebilir bir başlangıç metnidir; MEB rehberindeki örneğin aynısı değildir. MEB örneği PDF s. ${t.page} üzerinde görüntülenebilir.</div><div class="template-preview">${cleanHtml(t.html)}</div><div class="head-actions margin-top"><button type="button" class="btn" data-act="pdf-open-page" data-page="${t.page}">${icon('book')} PDF örneğini aç</button><button type="button" class="btn btn-primary" data-act="create-template" data-index="${i}">${icon('plus')} Bu şablonla belge oluştur</button></div>`,null)}
function documents(){const docs=state.cache.documents||[],chosen=byId('documents',state.docId);if(state.docId&&!chosen)state.docId=null;
 return `${titleBand('BAŞVURU BELGELERİ','Belge Stüdyosu','CV, niyet mektubu, araştırma özeti ve e-postaları hazırla, düzenle, Word olarak dışa aktar.',`${btn('Yeni belge','add-document','plus','btn-primary')}${btn('Şablonlar','choose-template','book')}`)}<div class="studio-grid"><section class="premium-panel doc-library">${blockHeading('Belgelerim','file',`<button type="button" class="doc-header-delete" data-act="delete-selected-document" title="${chosen?'Seçili belgeyi sil':'Silmek için belge seçin'}" aria-label="Seçili belgeyi sil" ${chosen?'':'disabled'}>${icon('trash',19)}</button>`)}<div class="doc-list">${docs.length?docs.map(x=>`<div class="doc-list-row"><button class="doc-list-item ${+x.id===+state.docId?'active':''}" data-act="doc-select" data-id="${x.id}">${icon('file',19)}<span><b>${esc(x.title)}</b><small>${esc(x.kind)} · ${esc(x.updated_at?.slice(0,10)||'')}</small></span>${icon('right',14)}</button></div>`).join(''):empty('Henüz kişisel belge yok','Şablondan belge oluştur veya yeni bir belge ekle.','choose-template','Şablon seç')}</div><div class="doc-sidebar-foot">${btn('Belge oluştur','choose-template','plus','btn-primary')}</div></section>
 <section class="premium-panel doc-editor-panel">${chosen?`<header class="editor-header"><div><h2>${esc(chosen.title)}</h2><p>${esc(chosen.kind)} · Cihazına otomatik kaydedilir</p></div><div class="editor-header-actions"><button class="btn btn-small" data-act="doc-export" data-id="${chosen.id}">${icon('download')} DOCX</button><button class="btn btn-small" data-edit="documents" data-id="${chosen.id}">${icon('edit')} Düzenle</button></div></header><div class="editor-tools"><button class="btn btn-small" data-act="format-doc" data-command="bold"><b>Kalın</b></button><button class="btn btn-small" data-act="format-doc" data-command="italic"><i>İtalik</i></button><button class="btn btn-small" data-act="format-doc" data-command="insertUnorderedList">${icon('task')} Liste</button><button class="btn btn-small" data-act="save-doc">${icon('save')} Kaydet</button><small class="muted" id="save-indicator">Tüm değişiklikler kaydedildi</small></div><div class="doc-paper-scroll"><div class="editor-body" contenteditable="true" role="textbox" aria-label="Belge düzenleyici" id="doc-editor" data-document-id="${chosen.id}">${cleanHtml(chosen.html)}</div></div>${chosen.source_page?`<div class="editor-footer"><button class="inline-link" data-act="pdf-page" data-page="${chosen.source_page}">MEB rehberi · PDF sayfa ${chosen.source_page} ${icon('external',14)}</button></div>`:''}`:empty('Belge düzenlemeye başla','Yeni belge oluşturabilir veya sağdaki hazır şablonlardan birini kullanabilirsin.','choose-template','Şablon seç')}</section>
 <section class="premium-panel studio-templates">${blockHeading('Şablon Kütüphanesi','book')}<p class="muted small">Başvuru belgeleri için düzenlenebilir taslaklar.</p><div class="template-catalog">${state.templates.map((t,i)=>`<div class="template-catalog-row"><div class="template-catalog-icon">${icon('file')}</div><div><strong>${esc(t.title)}</strong><small>Rehber ${esc(t.ref_key)} · PDF s. ${t.page}</small></div><div class="catalog-actions"><button data-act="preview-template" data-index="${i}" title="Şablonu ön izle" class="round-btn">${icon('search',16)}</button><button data-act="create-template" data-index="${i}" title="Şablondan oluştur" class="round-btn accent-btn">${icon('plus',16)}</button></div></div>`).join('')}</div></section></div>`
}
function ielts(){const all=state.cache.ielts_sessions||[],mins=all.reduce((s,x)=>s+(Number(x.minutes)||0),0),now=new Date(),period=state.ieltsPeriod||'all',skill=state.ieltsSkill||'all',sort=state.ieltsSort||'newest';let a=all.filter(x=>skill==='all'||x.skill===skill).filter(x=>{if(period==='all')return true;const d=new Date(String(x.date||'')+'T00:00:00'),days=(now-d)/86400000;if(Number.isNaN(d.getTime()))return false;return period==='day'?days>=0&&days<1:period==='week'?days>=0&&days<7:period==='month'?d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear():period==='year'?d.getFullYear()===now.getFullYear():true});a.sort((x,y)=>sort==='oldest'?String(x.date).localeCompare(String(y.date)):String(y.date).localeCompare(String(x.date)));const skills=['Listening','Reading','Writing','Speaking'],icons=['language','book','edit','users'];return `${titleBand('İNGİLİZCE HAZIRLIK','IELTS ve Dil Gelişimi','Dil hedeflerini ve çalışma oturumlarını düzenli biçimde takip et.',btn('Çalışma ekle','add-ielts','plus','btn-primary'))}<div class="metrics-4">${metric('Mevcut seviye',state.settings.cefr||'—','CEFR seviyesi','chart')}${metric('IELTS hedefi',state.settings.ielts_target||'—','Hedef toplam puan','flag')}${metric('Toplam çalışma',`${(mins/60).toFixed(1)} saat`,'Tüm kayıtlı oturumlar','clock')}${metric('Oturum sayısı',(state.cache.ielts_sessions||[]).length,'Tüm zamanlar','language')}</div><div class="ielts-layout"><div><section class="premium-panel">${blockHeading('Beceri özeti','chart')}<div class="skill-grid">${skills.map((sk,i)=>{let arr=all.filter(x=>x.skill===sk),m=arr.reduce((v,x)=>v+Number(x.minutes||0),0);return `<div class="skill-card">${icon(icons[i])}<h3>${sk}</h3><b>${(m/60).toFixed(1)} saat</b><small>${arr.length} oturum</small></div>`}).join('')}</div></section><section class="premium-panel margin-top">${blockHeading('Çalışma geçmişi','calendar',btn('Çalışma kaydet','add-ielts','plus'))}<div class="ielts-filters"><label>Beceri<select data-act="ielts-filter-skill"><option value="all">Tüm beceriler</option>${['Listening','Reading','Writing','Speaking','Grammar','Vocabulary','Academic English','Mock Test'].map(v=>`<option value="${v}" ${skill===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Sıralama<select data-act="ielts-filter-sort"><option value="newest" ${sort==='newest'?'selected':''}>Yeniden eskiye</option><option value="oldest" ${sort==='oldest'?'selected':''}>Eskiden yeniye</option></select></label><label>Dönem<select data-act="ielts-filter-period"><option value="all" ${period==='all'?'selected':''}>Tüm zamanlar</option><option value="day" ${period==='day'?'selected':''}>Bugün</option><option value="week" ${period==='week'?'selected':''}>Bu hafta</option><option value="month" ${period==='month'?'selected':''}>Bu ay</option><option value="year" ${period==='year'?'selected':''}>Bu yıl</option></select></label></div>${a.length?a.map(x=>`<div class="related-item"><div><b>${esc(x.skill)} · ${Number(x.minutes)} dakika</b><small>${fmtDate(x.date)} ${x.score?' · Puan: '+esc(x.score):''}</small>${x.note?`<small>${esc(truncate(x.note,120))}</small>`:''}</div><div class="list-row-actions"><button class="round-btn" data-delete="ielts_sessions" data-id="${x.id}" title="Sil">${icon('trash')}</button><button class="round-btn" data-edit="ielts_sessions" data-id="${x.id}" title="Düzenle">${icon('edit')}</button></div></div>`).join(''):empty('Bu seçimde çalışma yok','Filtreleri değiştir veya yeni bir oturum kaydet.','add-ielts','Çalışma ekle')}</section></div><section class="premium-panel">${blockHeading('Dil hedefleri','flag')}<p class="muted small">Kişisel seviyeni ve ulaşmak istediğin IELTS puanını belirle.</p><div class="field"><label for="cefr">Mevcut İngilizce seviyen</label><select id="cefr" class="form-control"><option value="">Belirlenmedi</option>${['A1','A2','A2+','B1','B1+','B2','C1','C2'].map(x=>`<option ${x===state.settings.cefr?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="target">IELTS Academic hedef puanın</label><input class="form-control" id="target" value="${attr(state.settings.ielts_target||'')}" placeholder="Örn. 7.0"/></div><div class="field"><label for="course-end">Dil eğitimi bitiş tarihi</label><input id="course-end" class="form-control" type="date" value="${attr(state.settings.course_end||'')}"/></div>${btn('Hedefleri kaydet','save-ielts-settings','save','btn-primary')}<div class="section-divider"></div><p class="detail-body">Dil puanı koşullarını hedef üniversitenin resmî program sayfasından doğrula.</p></section></div>`}
function administration(){let list=(state.cache.tasks||[]).filter(x=>['YLSY','Pasaport'].includes(x.track));return `${heading('Bursiyerlik & idari işlemler','YLSY & Pasaport','REBUS, resmî öğrenime başlama süreleri, pasaport ve vize hazırlığını kendi görevlerinle takip et.',btn('İdari görev ekle','add-admin-task','plus','btn-primary'))}<div class="grid2">${card('YLSY işlemleri',`<div class="helper-note">Öğrenime başlama süresi ve ülke/alan uygunluğu bursiyerliğinle ilgili resmî MEB belgelerinden teyit edilmelidir. Bu uygulama idari onay vermez.</div><div class="margin-top">${btn('REBUS’u normal tarayıcıda aç','open-rebus','external')}</div><p class="subtle tiny">Ayarlar bölümünden seçtiğin normal tarayıcı profili kullanılır. Şifreyi otomatik doldurmak tarayıcınızın kendi ayarlarına bağlıdır.</p>`)}${card('Pasaport ve vize',`<div class="helper-note">Pasaport başvurusu ve vize süreci farklı aşamalardır. ABD vize formları kabul ve ilgili üniversite belgeleri sonrası tamamlanır.</div><div class="margin-top">${btn('Pasaport randevu sitesi','open-nvi','external')}</div>`)}</div><div class="margin-top">${card('İdari görevlerim',list.length?list.map(taskRow).join(''):empty('İdari görev yok','Örneğin MEB teyidi, REBUS, pasaport randevusu gibi işleri kendi gerçek durumuna göre kaydet.','add-admin-task','İlk idari görevi ekle'))}</div>`}
function vocabularyQuiz(){const quiz=state.vocabQuiz;if(!quiz)return '';const words=state.cache.vocabulary||[];if(quiz.index>=quiz.ids.length)return `<section class="premium-panel vocab-quiz-result"><div class="vocab-quiz-icon">${icon('sparkle',30)}</div><h2>Quiz tamamlandı</h2><p>${quiz.known} / ${quiz.ids.length} kelimeyi hatırladın.</p><div class="title-actions">${btn('Yeniden başla','start-vocab-quiz','refresh')}${btn('Kelime listesine dön','stop-vocab-quiz','left')}</div></section>`;const word=words.find(x=>+x.id===+quiz.ids[quiz.index]);if(!word)return '';return `<section class="premium-panel vocab-quiz"><div class="vocab-quiz-top"><span class="eyebrow">KELİME QUIZİ</span><span class="pill">${quiz.index+1} / ${quiz.ids.length}</span></div><h2>${esc(word.word)}</h2><p>Bu kelimenin anlamı nedir?</p>${quiz.revealed?`<div class="vocab-answer"><strong>${esc(word.meaning)}</strong>${word.example?`<p>${esc(word.example)}</p>`:''}${word.note?`<small>${esc(word.note)}</small>`:''}</div><div class="vocab-quiz-actions"><button class="btn btn-danger" data-act="vocab-rate" data-known="false">Tekrar et</button><button class="btn btn-primary" data-act="vocab-rate" data-known="true">Hatırladım</button></div>`:`<button class="btn btn-primary" data-act="vocab-reveal">Cevabı göster</button>`}</section>`}
function vocabulary(){const all=state.cache.vocabulary||[],known=all.reduce((n,x)=>n+Number(x.known_count||0),0);let words=all.slice();if(state.vocabSort==='alpha')words.sort((a,b)=>a.word.localeCompare(b.word,'en',{sensitivity:'base'}));else if(state.vocabSort==='alpha-desc')words.sort((a,b)=>b.word.localeCompare(a.word,'en',{sensitivity:'base'}));else if(state.vocabSort==='oldest')words.sort((a,b)=>a.created_at.localeCompare(b.created_at));else if(state.vocabSort==='review')words.sort((a,b)=>Number(a.review_count||0)-Number(b.review_count||0)||b.created_at.localeCompare(a.created_at));else words.sort((a,b)=>b.created_at.localeCompare(a.created_at));const rows=words.map(x=>`<article class="vocab-row" data-match="${attr([x.word,x.meaning,x.example].join(' '))}"><div class="vocab-word-main"><div class="vocab-word-title"><h3>${esc(x.word)}</h3></div><p class="vocab-meaning multiline">${esc(x.meaning)}</p>${x.example?`<p class="vocab-example multiline">${esc(x.example)}</p>`:''}<small class="vocab-added">Eklendi: ${fmtDate(x.created_at)} · Quiz: ${Number(x.known_count||0)} / ${Number(x.review_count||0)} hatırlandı</small></div><div class="list-row-actions"><button class="round-btn" data-edit="vocabulary" data-id="${x.id}" title="Düzenle">${icon('edit')}</button><button class="round-btn" data-delete="vocabulary" data-id="${x.id}" title="Sil">${icon('trash')}</button></div></article>`).join('');return `${titleBand('KİŞİSEL KELİME ÇALIŞMASI','Kelime Defterim','IELTS ve akademik İngilizce için kelimelerini, anlamlarını ve örnek cümlelerini biriktir. Quiz ile hafızanı yokla.',`${btn('Kelime ekle','add-vocabulary','plus','btn-primary')}${btn('Quiz başlat','start-vocab-quiz','sparkle')}`)}<div class="metrics-3">${metric('Kelime sayısı',all.length,'Kişisel defterindeki kayıtlar','book')}${metric('Quiz tekrarları',all.reduce((n,x)=>n+Number(x.review_count||0),0),'Toplam hatırlama denemesi','refresh')}${metric('Hatırlanan cevaplar',known,'Quizde “Hatırladım” işaretlediklerin','check')}</div>${vocabularyQuiz()}<section class="premium-panel vocab-library">${blockHeading('Kelimelerim','book',btn('Yeni kelime','add-vocabulary','plus'))}<div class="vocab-browser list-with-filter"><div class="vocab-toolbar"><div class="field vocab-search"><label for="vocab-search">Kelime veya anlam ara</label><input id="vocab-search" class="form-control" type="search" placeholder="Örn. resilience, dayanıklılık…" data-live-filter/></div><div class="field vocab-sort"><label for="vocab-sort">Sıralama</label><select id="vocab-sort" class="form-control" data-act="vocab-sort"><option value="newest" ${state.vocabSort==='newest'?'selected':''}>En son eklenen</option><option value="oldest" ${state.vocabSort==='oldest'?'selected':''}>En eski eklenen</option><option value="alpha" ${state.vocabSort==='alpha'?'selected':''}>Alfabetik (A–Z)</option><option value="alpha-desc" ${state.vocabSort==='alpha-desc'?'selected':''}>Alfabetik (Z–A)</option><option value="review" ${state.vocabSort==='review'?'selected':''}>Önce az çalışılanlar</option></select></div></div><div class="vocab-list">${rows||empty('Kelime defterin henüz boş','İngilizce kelime ekle; Türkçe anlamları ve örnekleri otomatik getirelim.','add-vocabulary','İlk kelimeni ekle')}</div></section>`}
function upcoming(){let dates=[...(state.cache.events||[]).map(x=>({date:x.date,title:x.title,note:x.kind,kind:'event',id:x.id})),...(state.cache.programs||[]).filter(x=>x.deadline).map(x=>({date:x.deadline,title:x.university+' · '+x.name,note:x.deadline_verified?'Başvuru tarihi · doğrulandı':'Başvuru tarihi · doğrulanmadı',kind:'program',id:x.id})),...(state.cache.tasks||[]).filter(x=>x.due_date&&x.status!=='done').map(x=>({date:x.due_date,title:x.title,note:'Görev',kind:'task',id:x.id}))];return dates.sort((a,b)=>String(a.date).localeCompare(String(b.date)))}
function dateRow(x){return `<div class="date-item"><div class="date-pill"><b>${esc(String(x.date||'').slice(8,10))}</b><span>${esc(String(x.date||'').slice(0,7))}</span></div><div class="grow"><b style="font-size:12px">${esc(x.title)}</b><div class="tiny muted" style="margin-top:4px">${esc(x.note)}</div></div></div>`}
function calendar(){const events=upcoming(),now=new Date(),shownMonth=new Date(now.getFullYear(),now.getMonth()+(state.monthOffset||0),1),year=shownMonth.getFullYear(),month=shownMonth.getMonth();
 const first=(shownMonth.getDay()+6)%7,count=new Date(year,month+1,0).getDate();const cells=[];
 for(let c=0;c<Math.ceil((first+count)/7)*7;c++){const day=c-first+1;if(day<1||day>count){cells.push('<div class="cal-day muted-day"></div>');continue}const key=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const dayEvents=events.filter(e=>e.date===key);cells.push(`<div class="cal-day ${key===new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+'-'+String(new Date().getDate()).padStart(2,'0')?'today':''}"><span>${day}</span>${dayEvents.slice(0,3).map(e=>`<span class="event-dot" title="${attr(e.title)}"></span>`).join('')}${dayEvents.length>3?`<small>+${dayEvents.length-3}</small>`:''}</div>`)}
 return `${titleBand('ZAMAN VE PLANLAMA','Takvim ve Hatırlatmalar','Son başvuru tarihleri, kişisel görevler, sınavlar ve etkinlikler tek takvimde.',btn('Tarih ekle','add-event','plus','btn-primary'))}
 <div class="calendar-layout"><section class="premium-panel"><div class="flex-title"><h2>${new Intl.DateTimeFormat('tr-TR',{month:'long',year:'numeric'}).format(shownMonth)}</h2><div class="cal-arrows"><button class="round-btn" data-act="calendar-prev" title="Önceki ay">${icon('left')}</button><button class="round-btn" data-act="calendar-today" title="Bu ay">Bugün</button><button class="round-btn" data-act="calendar-next" title="Sonraki ay">${icon('right')}</button></div></div><div class="calendar-grid">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map(x=>`<div class="cal-weekday">${x}</div>`).join('')}${cells.join('')}</div><div class="legend"><span><i></i> En az bir kayıtlı etkinlik</span><span>Kaynak teyidi gereken tarihler, program sayfasında ayrıca işaretlenir.</span></div></section><section class="premium-panel">${blockHeading('Yaklaşan Etkinlikler','calendar')}<div class="calendar-events">${events.length?events.map(x=>`<div class="calendar-event">${dateRow(x)}${x.kind==='event'?`<button class="round-btn" data-edit="events" data-id="${x.id}">${icon('edit')}</button>`:''}</div>`).join(''):empty('Henüz bir tarih eklenmedi','Başvurular, görevler ve eklediğin etkinlikler burada listelenir.','add-event','Etkinlik ekle')}</div></section></div>`;
}
function files(){let a=state.cache.attachments||[];return `${heading('Yerel belge arşivi','Dosya Kasası','PDF ve diğer dosyaları uygulamaya ekleyip yerel cihazında sakla. Dosyalar buluta gönderilmez.',btn('Dosya ekle','upload-file','plus','btn-primary'))}${card('Dosyalarım',a.length?a.map(x=>`<div class="list-row"><div class="list-icon">${icon('paperclip')}</div><div class="list-row-main"><strong>${esc(x.original_name)}</strong><small>${(x.size/1024).toFixed(1)} KB · ${esc(x.owner_type)} · ${esc(x.updated_at?.slice(0,10)||'')}</small></div><div class="list-row-actions"><button class="round-btn" data-act="open-file" data-id="${x.id}" title="Dosyayı aç">${icon('external')}</button><button class="round-btn" data-act="delete-file" data-id="${x.id}" title="Sil">${icon('trash')}</button></div></div>`).join(''):empty('Dosya kasan boş','Transkript, diploma, sertifika ve diğer belgelerini ekleyebilirsin.','upload-file','Dosya ekle'))}`}
function notes(){const a=state.cache.notes||[];return `${titleBand('KİŞİSEL ARAŞTIRMA ALANI','Notlar','Başvuru araştırmalarını, toplantı notlarını ve fikirlerini tek yerde sakla.',btn('Yeni Not','add-note','plus','btn-primary'))}<section class="premium-panel">${blockHeading('Notlarım','file')}<div class="notes-grid">${a.length?a.map(x=>`<article class="note-card"><div class="note-heading"><h3>${esc(x.title)}</h3><span>${esc(x.category)}</span></div><p>${esc(x.body||'')}</p><div class="note-actions"><small>${esc(x.updated_at?.slice(0,10)||'')}</small><button class="btn" data-edit="notes" data-id="${x.id}">${icon('edit',14)} Düzenle</button><button class="round-btn" data-delete="notes" data-id="${x.id}" title="Sil">${icon('trash',16)}</button></div></article>`).join(''):empty('Henüz notun yok','Başvuru, danışman veya araştırma fikirleri hakkında not oluştur.','add-note','İlk notu oluştur')}</div></section>`}
function resources(){const a=state.cache.resources||[];return `${titleBand('ARAŞTIRMA KÜTÜPHANESİ','Kaynaklar & Yayınlar','Makaleleri, laboratuvar sayfalarını ve önemli bağlantıları kaydet.',btn('Kaynak Ekle','add-resource','plus','btn-primary'))}<section class="premium-panel">${blockHeading('Kaydedilen Kaynaklar','book')}<div class="resource-grid">${a.length?a.map(x=>`<div class="resource-row"><div class="resource-icon">${icon('book',21)}</div><div><strong>${esc(x.title)}</strong><p>${esc(x.note||x.kind)}</p>${link(x.url,'Kaynağı Aç')}</div><button class="round-btn" data-edit="resources" data-id="${x.id}" title="Düzenle">${icon('edit')}</button><button class="round-btn" data-delete="resources" data-id="${x.id}" title="Sil">${icon('trash')}</button></div>`).join(''):empty('Kaynak kütüphanen boş','Doğrulanmış araştırma bağlantıları, yayınlar veya önemli sayfaları ekle.','add-resource','İlk kaynağı ekle')}</div></section>`}
function settings(){return `${heading('Veri güvenliği','Ayarlar ve yedekleme','Verilerini yedekle, geri yükle ve bulut bağlantı durumunu buradan yönet.') }<div class="grid2">${card('Cihaz yedeği',`<div class="subline">Tüm çalışma kayıtlarını, IELTS oturumlarını ve kelime defterini arşiv olarak indir.</div><div class="head-actions margin-top">${btn('Yedek indir','backup','download','btn-primary')}${btn('Yedeği geri yükle','restore','upload')}</div><div class="helper-note margin-top">Geri yükleme öncesinde mevcut verilerin için otomatik geri dönüş yedeği oluşturulur.</div>`)}${card('Görevleri dışa aktar',`<div class="subline">Görev listeni Excel ile açılabilen CSV dosyası olarak al.</div><div class="head-actions margin-top">${btn('Görevleri indir','export-csv','download')}${btn('MEB rehberini aç','pdf-new','book')}</div>`)}</div><div class="margin-top">${card('Google Drive yedekleme',`<div class="subline">Hesabını bağladıktan sonra kayıtların değiştikçe otomatik yedeklenir. Bağlantı yoksa işlemler güvenli yerel kuyrukta bekler ve internet gelince gönderilir.</div><div id="settings-cloud-status" class="helper-note margin-top">Bulut bağlantı durumunu üst çubuktan görebilirsin.</div><div class="margin-top">${btn('Google Drive bağlantısını yönet','cloud-settings','cloud','btn-primary')}</div>`)}</div><div class="margin-top">${card('Uygulama bilgileri',`<div class="subline"><b>YLSY Atlas 2.4.3</b> · Güvenli yerel kayıt ve otomatik bulut yedekleme<br>MEB ABD başvuru rehberi: 60 sayfa.</div>`)}</div>`}
const definitions={
 universities:{title:'Üniversite',fields:[['name','Üniversite resmî adı','text',1],['short','Kısa ad','text',1],['country','Ülke','text'],['city','Şehir','text'],['url','Üniversitenin resmî sayfası','url'],['ylsy_status','YLSY uygunluğu','select',0,['Doğrulanmadı','Araştırılıyor','Uygunluğu teyit edildi','Uygun değil']],['rank','Kendi liste sıram','number'],['note','Araştırma notları','textarea']]},
 programs:{title:'Doktora programı',fields:[['university_id','Üniversite','universities',1],['name','Programın adı','text',1],['laboratory','Laboratuvar / araştırma grubu','text'],['research','Çalışma alanı','textarea'],['deadline','Son başvuru tarihi','date'],['deadline_verified','Tarih resmî kaynaktan doğrulandı mı?','checkbox'],['stage','Başvuru durumu','select',0,['Araştırılıyor','Danışman iletişimi','Başvuru hazırlanıyor','Başvuru gönderildi','Bekleme listesi','Kabul','Ret','Vazgeçildi']],['url','Programın resmî bağlantısı','url'],['note','Notlar','textarea']]},
 advisors:{title:'Danışman',fields:[['university_id','Üniversite','universities',1],['program_id','İlgili doktora programı','programs'],['name','Akademisyen adı','text',1],['topic','Araştırma alanları','textarea'],['email','Kurumsal e-posta','email'],['url','Akademisyen sayfası','url'],['status','İletişim durumu','select',0,['Araştırılıyor','E-posta hazır','E-posta gönderildi','Yanıt bekleniyor','Görüşme yapıldı','Olumlu yanıt','Öğrenci kabul etmiyor','İletişim kapatıldı']],['last_contact','Son iletişim tarihi','date'],['note','Yayınlar / önemli notlar','textarea']]},
 tasks:{title:'Görev',fields:[['title','Görev başlığı','text',1],['group_name','Aşama / grup','text'],['track','Çalışma hattı','select',0,['Rehber','IELTS','Akademik','YLSY','Pasaport','Başvuru','Kişisel']],['status','Durum','select',0,[['todo','Yapılacak'],['doing','Devam ediyor'],['done','Tamamlandı']]],['due_date','Son tarih','date'],['priority','Öncelik','select',0,['Düşük','Normal','Yüksek','Kritik']],['note','Açıklama / kaynak','textarea']]},
 documents:{title:'Metin belgesi',fields:[['title','Belge başlığı','text',1],['kind','Belge türü','select',0,['Genel','CV','SoP','E-posta','Referans','Araştırma','Research Statement','Personal Statement','Writing Sample']],['source_page','Kaynak PDF sayfası','number']]},
 ielts_sessions:{title:'IELTS çalışma oturumu',fields:[['date','Tarih','date',1],['skill','Çalışılan beceri','select',1,['Listening','Reading','Writing','Speaking','Grammar','Vocabulary','Academic English','Mock Test']],['minutes','Süre (dakika)','number',1],['score','Deneme sonucu (isteğe bağlı)','text'],['note','Çalışma notları','textarea']]},
 vocabulary:{title:'Kelime',fields:[['word','İngilizce kelime','text',1],['meaning','Türkçe anlamları (satır satır)','textarea',1],['example','Örnek cümleler','textarea']]},
  notes:{title:'Not',fields:[['title','Not başlığı','text',1],['category','Not grubu (ör. başvuru, danışman, araştırma)','text'],['body','Not içeriği','textarea']]},
  resources:{title:'Kaynak / yayın',fields:[['title','Kaynak başlığı','text',1],['url','Resmî bağlantı / DOI adresi','url'],['kind','Tür','select',0,['Makale','Laboratuvar','Üniversite','Rehber','Diğer']],['note','Notlar','textarea']]},
 events:{title:'Takvim etkinliği',fields:[['date','Etkinlik tarihi','date',1],['title','Başlık','text',1],['kind','Etkinlik türü','select',0,['Genel','IELTS','Başvuru','Danışman','YLSY','Pasaport','Vize','Sınav']],['note','Notlar','textarea']]}
};
const defaults={universities:{country:'',ylsy_status:'Doğrulanmadı',rank:99},programs:{stage:'Araştırılıyor',deadline_verified:0},advisors:{status:'Araştırılıyor'},tasks:{group_name:'Genel',track:'Kişisel',status:'todo',priority:'Normal'},documents:{kind:'Genel'},ielts_sessions:{minutes:30},vocabulary:{tags:'IELTS'},events:{kind:'Genel'}};
function selectOptions(table,record){if(table==='universities')return (state.cache.universities||[]).map(u=>[u.id,u.short||u.name]);return (state.cache.programs||[]).filter(p=>!record?.university_id||p.university_id===Number(record.university_id)).map(p=>[p.id,`${p.university} · ${p.name}`])}
function fieldHtml(row,data,table){let [key,lbl,type,required,opts]=row,v=data[key]??'',id='form-'+key;let inner='';if(type==='textarea')inner=`<textarea id="${id}" name="${key}" ${required?'required':''} rows="4" placeholder="${attr(lbl)}">${esc(v)}</textarea>`;else if(type==='select'||type==='universities'||type==='programs'){let options=type==='select'?opts.map(o=>Array.isArray(o)?o:[o,o]):selectOptions(type,data);inner=`<select id="${id}" name="${key}" ${required?'required':''}><option value="">${type==='select'?'Seçiniz':'İlişkilendirilecek kaydı seçin'}</option>${options.map(([value,title])=>`<option value="${attr(value)}" ${String(v)===String(value)?'selected':''}>${esc(title)}</option>`).join('')}</select>`}else if(type==='checkbox')inner=`<label style="display:flex;gap:8px;align-items:center;color:#d6e8f5"><input type="checkbox" style="width:18px;height:18px;min-height:18px" name="${key}" id="${id}" ${Number(v)?'checked':''}/> Evet, resmî kaynaktan kontrol ettim</label>`;else inner=`<input id="${id}" name="${key}" type="${type}" value="${attr(v)}" ${type==='number'?'min="0"':''} ${required?'required':''} placeholder="${attr(lbl)}"/>`;return `<div class="field ${type==='textarea'?'span2':''}"><label for="${id}">${esc(lbl)} ${required?'*':''}</label>${inner}</div>`}
function modal(title,content,onSubmit=null,submitText='Kaydet'){const root=$('#modal-root');root.innerHTML=`<div class="modal-shade" data-act="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${attr(title)}"><div class="modal-top"><h2>${esc(title)}</h2><button class="icon-button" data-act="close-modal" title="Kapat">${icon('close')}</button></div><form id="modal-form"><div class="modal-content">${content}</div><div class="modal-actions"><button type="button" class="btn" data-act="close-modal">İptal</button>${onSubmit?`<button type="submit" class="btn btn-primary">${icon('save')} ${esc(submitText)}</button>`:''}</div></form></div></div>`;root._submit=onSubmit;if(onSubmit){$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();let f=e.currentTarget;let button=f.querySelector('[type=submit]');button.disabled=true;try{await onSubmit(f);closeModal()}catch(err){toast(err.message,true)}finally{button.disabled=false}})}let input=root.querySelector('input:not([type=checkbox]),select');if(input)setTimeout(()=>input.focus(),50)}
function closeModal(){$('#modal-root').replaceChildren()}
function errorMessage(e){toast(e.message||'İşlem başarısız',true)}
async function saveData(table,data,id){await api(table+(id?'/'+id:''),id?'PUT':'POST',data);await reload([table]);render();toast(id?'Değişiklik kaydedildi':'Yeni kayıt eklendi')}
function openForm(table,id=null,preset={}){let def=definitions[table];if(!def)return;let previous=id?byId(table,id):null;let d={...(defaults[table]||{}),...preset,...previous};if(table==='programs'&&!state.cache.universities.length){toast('Önce üniversite kaydı ekle',true);openForm('universities');return}if(table==='advisors'&&!state.cache.universities.length){toast('Önce üniversite kaydı ekle',true);openForm('universities');return}if(table==='ielts_sessions'&&!d.date)d.date=new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+'-'+String(new Date().getDate()).padStart(2,'0');if(table==='events'&&!d.date)d.date=new Date().getFullYear()+'-'+String(new Date().getMonth()+1).padStart(2,'0')+'-'+String(new Date().getDate()).padStart(2,'0');if(table==='tasks'&&preset.guide_key)d.guide_key=preset.guide_key;const html=`<div class="form-grid">${def.fields.map(x=>fieldHtml(x,d,table)).join('')}</div>${table==='vocabulary'?'<div id="dictionary-hint" class="helper-note span2">Kelimeyi yazınca çevrimiçi anlam ve örnekler aranır. Sonucu gözden geçirip kaydedebilirsin.</div>':''}${table==='programs'?'<div class="helper-note">Son başvuru tarihi ayrıca doğrulandığını işaretlemeden kesin kabul edilmez.</div>':''}${table==='vocabulary'?'<div id="dictionary-hint" class="helper-note span2">Kelimeyi yazınca anlam ve örnek cümleler aranır. Sonucu gözden geçirip kaydedebilirsin.</div>':''}`;
 modal((id?'Düzenle: ':'Yeni ')+def.title,html,async f=>{let out={};for(let [key,lbl,type,required]of def.fields){let el=f.elements.namedItem(key);if(!el)continue;let v=type==='checkbox'?(el.checked?1:0):el.value.trim();if(required&&!v)throw new Error(lbl+' boş olamaz');out[key]=v}if(table==='advisors'&&out.program_id){let match=byId('programs',out.program_id);if(!match||Number(match.university_id)!==Number(out.university_id))throw new Error('Danışmanın programı ve üniversitesi eşleşmiyor')}if(table==='documents'&&!id){out.html=String(preset.html||'');if(preset.ref_key)out.ref_key=preset.ref_key}if(table==='tasks'&&preset.guide_key){out.guide_key=preset.guide_key;out.source_page=preset.source_page||0}let saved=await api(table+(id?'/'+id:''),id?'PUT':'POST',out);await reload([table]);if(table==='documents'){state.docId=saved.id;state.nav='documents'}render();toast('Kaydedildi')});
 const u=$('#form-university_id'),pr=$('#form-program_id');if(u&&pr){u.addEventListener('change',()=>{let options=selectOptions('programs',{university_id:Number(u.value)});pr.innerHTML=`<option value="">Program seçilmedi</option>${options.map(([v,n])=>`<option value="${v}">${esc(n)}</option>`).join('')}`})}}
async function deleteRecord(table,id){let entry=byId(table,id);let text=entry?.name||entry?.title||entry?.word||entry?.original_name||'bu kayıt';let extra=table==='universities'?' Bu üniversiteye bağlı bütün programlar ve danışmanlar da silinir.':'';if(!confirm('“'+text+'” kalıcı olarak silinsin mi?'+extra))return;try{if(table==='documents'){clearTimeout(state.docTimer);state.docTimer=null;}if(table==='vocabulary')state.vocabQuiz=null;await api(table+'/'+id,'DELETE');if(table==='documents'&&state.docId===Number(id))state.docId=null;await reload(table==='universities'?['universities','programs','advisors']:table==='programs'?['programs','advisors']:[table]);render();toast('Kayıt silindi')}catch(e){errorMessage(e)}}
function cleanHtml(source){const el=document.createElement('template');el.innerHTML=String(source||'');const whitelist=new Set(['H1','H2','H3','H4','P','BR','DIV','SPAN','STRONG','B','EM','I','U','UL','OL','LI','BLOCKQUOTE','HR','A']);function sanitize(node){for(const c of [...node.childNodes]){if(c.nodeType===1){if(!whitelist.has(c.tagName)){let text=document.createTextNode(c.textContent||'');c.replaceWith(text);continue}let href=c.tagName==='A'?c.getAttribute('href'):null;for(const a of [...c.attributes])c.removeAttribute(a.name);if(href&&/^https?:\/\//i.test(href))c.setAttribute('href',href);sanitize(c)}else if(c.nodeType!==3)c.remove()}}sanitize(el.content);return el.innerHTML}
async function saveDocument(){let editor=$('#doc-editor');if(!editor)return;let id=Number(editor.dataset.documentId);if(!id)return;let html=cleanHtml(editor.innerHTML);let indicator=$('#save-indicator');if(indicator)indicator.textContent='Kaydediliyor…';try{await api('documents/'+id,'PUT',{html});let docs=state.cache.documents||[],d=docs.find(x=>x.id===+id);if(d)d.html=html;if(indicator&&$('#doc-editor')===editor)indicator.textContent='Kaydedildi'}catch(e){if(indicator&&$('#doc-editor')===editor)indicator.textContent='Kayıt başarısız';errorMessage(e)}}
function chooseTemplate(){let templates=state.templates;modal('Belge şablonu seç',`<div class="list-rows">${templates.map((t,i)=>`<button type="button" class="list-row" data-act="create-template" data-index="${i}" style="width:100%;text-align:left;cursor:pointer"><span class="list-icon">${icon('file')}</span><span class="list-row-main"><strong>${esc(t.title)}</strong><small>Rehber ${esc(t.ref_key)} · PDF sayfa ${t.page} · Yeni kişisel belge oluştur</small></span>${icon('right')}</button>`).join('')}</div>`,null)}
async function createTemplate(i){let t=state.templates[i];if(!t)return;try{clearTimeout(state.docTimer);await saveDocument();let d=await api('documents','POST',{title:t.title,kind:t.kind,ref_key:t.ref_key,source_page:t.page,html:t.html});await reload(['documents']);state.docId=d.id;closeModal();nav('documents');toast('Şablondan yeni belge oluşturuldu')}catch(e){errorMessage(e)}}
function saveFile(name,blob){if(window.AndroidAtlas?.saveFile){let reader=new FileReader();reader.onload=()=>{try{AndroidAtlas.saveFile(name,String(reader.result).split(',').pop(),blob.type||'application/octet-stream')}catch(e){toast('Dosya dışa aktarılamadı',true)}};reader.onerror=()=>toast('Dosya okunamadı',true);reader.readAsDataURL(blob);return}let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),9000)}
async function download(endpoint,name){try{let response=await fetch('/api/'+endpoint,{headers:{'X-Atlas-Token':TOKEN}});if(!response.ok)throw new Error('Dosya alınamadı');saveFile(name,await response.blob());toast('Dosya hazırlandı')}catch(e){errorMessage(e)}}
async function uploadFile(file){if(!file)return;if(file.size>20*1024*1024){toast('En fazla 20 MB dosya yükleyebilirsin',true);return}let bytes=await file.arrayBuffer(),array=new Uint8Array(bytes),parts=[];for(let i=0;i<array.length;i+=8192)parts.push(String.fromCharCode(...array.subarray(i,i+8192)));let base64=btoa(parts.join(''));try{await api('attachments','POST',{name:file.name,mime:file.type||'application/octet-stream',owner_type:'general',owner_id:0,content:base64});await reload(['attachments','notes','resources']);render();toast('Dosya eklendi')}catch(e){errorMessage(e)}}
async function restoreBackup(file){if(!file)return;if(!confirm('Yedek geri yüklenecek; mevcut veriler yedeklenerek değiştirilecek. Devam edilsin mi?'))return;let buf=await file.arrayBuffer(),a=new Uint8Array(buf),s=[];for(let i=0;i<a.length;i+=8192)s.push(String.fromCharCode(...a.subarray(i,i+8192)));try{await api('restore','POST',{content:btoa(s.join(''))});await reload(['universities','programs','advisors','tasks','documents','ielts_sessions','vocabulary','events','attachments','notes','resources']);state.docId=null;render();toast('Yedek başarıyla geri yüklendi')}catch(e){errorMessage(e)}}
function openSearch(){let root=$('#search-root');root.innerHTML=`<div class="search-shade" data-act="close-search"><div class="search-modal"><input id="global-search" type="search" placeholder="Üniversite, danışman, kelime veya belge ara…" autocomplete="off" aria-label="Genel arama"/><div class="search-results" id="search-results"><div class="empty tiny">Aramak için yazmaya başla · Esc ile kapat</div></div></div></div>`;root.querySelector('input').focus();let t;root.querySelector('input').addEventListener('input',e=>{clearTimeout(t);t=setTimeout(async()=>{try{let q=e.target.value.trim();let g=state.guideList.filter(x=>x.title.toLocaleLowerCase('tr').includes(q.toLocaleLowerCase('tr'))||x.id.toLocaleLowerCase('tr')===q.toLocaleLowerCase('tr')).slice(0,6);let results=q.length>1?await api('search?q='+encodeURIComponent(q)):[];let html=[...results.map(x=>`<button class="search-result" data-act="search-select" data-table="${x.type}" data-id="${x.id}">${icon('search')}<span>${esc(x.title)}<small>${esc(x.subtitle)}</small></span></button>`),...g.map(x=>`<button class="search-result" data-act="search-guide" data-guide="${attr(x.id)}">${icon('book')}<span>${esc(x.title)}<small>Rehber ${esc(x.id)} · sayfa ${x.page}</small></span></button>`)].join('');$('#search-results').innerHTML=html||'<div class="empty">Sonuç bulunamadı</div>'}catch(e){toast(e.message,true)}},250)})}
async function execute(action,el){try{switch(action){case 'retry':return start();case 'close-modal':return closeModal();case 'close-search':return $('#search-root').replaceChildren();case 'open-search':return openSearch();case 'open-guide':return nav('guide');case 'guide-pdf-import':return filePicker('guide-pdf');case 'open-roadmap':return nav('roadmap');case 'goto-applications':return nav('applications');case 'goto-ielts':return nav('ielts');case 'goto-calendar':return nav('calendar');case 'back-universities':return nav('universities');case 'add-university':return openForm('universities');case 'add-program':return openForm('programs',null,state.detailId&&state.nav==='universities'?{university_id:state.detailId}:{});case 'add-advisor':return openForm('advisors',null,state.detailId&&state.nav==='universities'?{university_id:state.detailId}:{});case 'add-task':return openForm('tasks');case 'add-admin-task':return openForm('tasks',null,{track:'YLSY',group_name:'İdari'});case 'add-ielts':return openForm('ielts_sessions');case 'add-event':return openForm('events');case 'add-note':return openForm('notes');case 'add-resource':return openForm('resources');case 'set-focus':{return modal('Araştırma Odak Alanı',`<p class="muted tiny">Bu alan kişisel çalışma verisidir; yeni kullanıcılar için başlangıçta boştur.</p><div class="field"><label for="research-focus">Araştırma başlığı</label><input id="research-focus" name="research_focus" class="form-control" maxlength="180" value="${attr(state.settings.research_focus||'')}" placeholder="Örn. Türbin soğutması ve aerotermal tasarım"/></div><div class="field"><label for="research-tags">Anahtar kelimeler (virgülle ayır)</label><input id="research-tags" name="research_tags" class="form-control" maxlength="250" value="${attr(state.settings.research_tags||'')}" placeholder="Örn. CFD, CHT, Yapısal Ömür"/></div>`,async f=>{state.settings=await api('settings','POST',{research_focus:f.elements.namedItem('research_focus').value,research_tags:f.elements.namedItem('research_tags').value});render();toast('Araştırma alanı kaydedildi')},'Kaydet')};case 'add-vocabulary':return openForm('vocabulary');case 'vocab-sort':state.vocabSort=el.value;return render();case 'ielts-filter-skill':state.ieltsSkill=el.value;return render();case 'ielts-filter-sort':state.ieltsSort=el.value;return render();case 'ielts-filter-period':state.ieltsPeriod=el.value;return render();case 'cloud-settings':document.getElementById('profile-button')?.click();return; case 'start-vocab-quiz':{let words=state.cache.vocabulary||[];if(!words.length){toast('Önce kelime defterine birkaç kelime ekle.',true);return}state.vocabQuiz={ids:words.slice().sort(()=>Math.random()-.5).map(x=>x.id),index:0,revealed:false,known:0};return render()}case 'stop-vocab-quiz':state.vocabQuiz=null;return render();case 'vocab-reveal':if(state.vocabQuiz)state.vocabQuiz.revealed=true;return render();case 'vocab-rate':{let q=state.vocabQuiz;if(!q)return;let word=byId('vocabulary',q.ids[q.index]),known=el.dataset.known==='true';let updated=await api('vocabulary/'+word.id+'/review','POST',{known});state.cache.vocabulary=state.cache.vocabulary.map(x=>+x.id===+updated.id?updated:x);if(known)q.known++;q.index++;q.revealed=false;return render()}case 'add-document':return openForm('documents');case 'filter-tasks':state.filter=el.dataset.value;return render();case 'guide-select':state.guide=Number(el.dataset.index);return render();case 'select-university':state.selectedUniversity=Number(el.dataset.id);state.detailId=state.selectedUniversity;return render();case 'select-advisor':state.selectedAdvisor=Number(el.dataset.id);return render();case 'advisor-email':return chooseTemplate();case 'calendar-prev':state.monthOffset--;return render();case 'calendar-next':state.monthOffset++;return render();case 'calendar-today':state.monthOffset=0;return render();case 'guide-task':{let g=state.guideList[state.guide];return openForm('tasks',null,{guide_key:g.id,title:g.id+' · '+g.title,source_page:g.page,track:'Rehber',group_name:g.group})}case 'pdf-page':{let x=state.guideList.findIndex(g=>g.page===Number(el.dataset.page));if(x>=0)state.guide=x;return nav('guide')}case 'pdf-new':{if(!state.guidePdf?.available){toast('Önce MEB PDF dosyasını ekle.',true);return filePicker('guide-pdf')}let g=state.guideList[state.guide];return window.open(pdfUrl(state.nav==='guide'?(g?.page||1):1),'_blank','noopener')}case 'template-this':{let g=state.guideList[state.guide];let index=state.templates.findIndex(t=>t.ref_key===g.id);return createTemplate(index)}case 'choose-template':return chooseTemplate();case 'preview-template':return previewTemplate(Number(el.dataset.index));case 'pdf-open-page':if(!state.guidePdf?.available){toast('Önce MEB PDF dosyasını ekle.',true);return filePicker('guide-pdf')}return window.open(pdfUrl(Number(el.dataset.page)||1),'_blank','noopener');case 'create-template':return createTemplate(Number(el.dataset.index));case 'doc-select':{clearTimeout(state.docTimer);await saveDocument();state.docId=Number(el.dataset.id);return render()}case 'delete-selected-document':{if(!state.docId || !byId('documents',state.docId)){toast('Önce silinecek belgeyi seçin.',true);return}return deleteRecord('documents',state.docId)}case 'doc-export':await saveDocument();return download('documents/'+el.dataset.id+'/export.docx','YLSY-Atlas-Belge.docx');case 'format-doc':{let editor=$('#doc-editor');if(!editor)return;editor.focus();document.execCommand(el.dataset.command,false,null);return scheduleDoc()}case 'save-doc':return saveDocument();case 'university-detail':return universityDetail(Number(el.dataset.id));case 'toggle-task':{let x=byId('tasks',el.dataset.id);await api('tasks/'+x.id,'PUT',{status:x.status==='done'?'todo':'done'});await reload(['tasks']);return render()}case 'save-ielts-settings':{await api('settings','POST',{cefr:$('#cefr').value,ielts_target:$('#target').value,course_end:$('#course-end').value});state.settings=await api('settings');render();return toast('Dil hedeflerin kaydedildi')}case 'backup':return download('backup','YLSY-Atlas-Yedek.zip');case 'export-csv':return download('tasks.csv','YLSY-Atlas-Gorevler.csv');case 'restore':return filePicker('restore');case 'upload-file':return filePicker('upload');case 'open-file':{let id=Number(el.dataset.id),x=byId('attachments',id);if(!x)return;if(x.mime==='application/pdf'||x.mime.startsWith('image/'))return window.open('/api/attachments/'+id+'/file?token='+encodeURIComponent(TOKEN),'_blank','noopener');let r=await fetch('/api/attachments/'+id+'/file',{headers:{'X-Atlas-Token':TOKEN}});return saveFile(x.original_name,await r.blob())}case 'delete-file':{let id=Number(el.dataset.id),x=byId('attachments',id);if(!confirm('“'+x.original_name+'” dosyası silinsin mi?'))return;await api('attachments/'+id,'DELETE');await reload(['attachments']);render();return toast('Dosya silindi')}case 'open-rebus':{let r=await api('open-external','POST',{site:'rebus'});return toast(r.message)}case 'open-nvi':{let r=await api('open-external','POST',{site:'nvi'});return toast(r.message)}case 'search-select':{let type=el.dataset.table,id=Number(el.dataset.id);$('#search-root').replaceChildren();if(type==='universities'){nav('universities');return universityDetail(id)}if(type==='documents'){state.docId=id;return nav('documents')}nav(type==='tasks'?'roadmap':type);return}case 'search-guide':{let i=state.guideList.findIndex(g=>g.id===el.dataset.guide);if(i>=0)state.guide=i;$('#search-root').replaceChildren();return nav('guide')}default:return}}catch(e){errorMessage(e)}}
async function importGuidePdf(file){
 if(!file)return;
 if(file.size>40*1024*1024||file.size<100){toast('PDF dosyası 40 MB altında olmalıdır.',true);return}
 const bytes=new Uint8Array(await file.arrayBuffer());
 if(new TextDecoder().decode(bytes.subarray(0,5))!=='%PDF-'){toast('Geçerli bir PDF dosyası seçmelisin.',true);return}
 const chunks=[];for(let i=0;i<bytes.length;i+=8192)chunks.push(String.fromCharCode(...bytes.subarray(i,i+8192)));
 try{toast('PDF uygulamaya ekleniyor…');await api('guide-pdf/import','POST',{content:btoa(chunks.join(''))});state.guidePdf=await api('guide-pdf/status');render();toast('MEB rehberi kaydedildi ve görüntüleyiciye eklendi.')}
 catch(e){errorMessage(e)}
}
function filePicker(mode){let inp=$('#hidden-file');inp.value='';inp.accept=mode==='restore'?'.zip':mode==='guide-pdf'?'.pdf,application/pdf':'*/*';inp.onchange=()=>mode==='restore'?restoreBackup(inp.files[0]):mode==='guide-pdf'?importGuidePdf(inp.files[0]):uploadFile(inp.files[0]);inp.click()}
function scheduleDoc(){let el=$('#save-indicator');if(el)el.textContent='Değişiklik var…';clearTimeout(state.docTimer);state.docTimer=setTimeout(saveDocument,800)}
function wire(){if(eventsBound)return;eventsBound=true;if(!history.state?.atlasPage)history.replaceState({atlasPage:state.nav},'','#'+state.nav);window.addEventListener('popstate',e=>{const page=e.state?.atlasPage;if(page&&page in names)nav(page,true)});window.addEventListener('online',()=>api('cloud/sync-now','POST').catch(()=>{}));document.addEventListener('click',async e=>{let target=e.target instanceof Element?e.target:e.target?.parentElement;if(!target)return;let navElement=target.closest('[data-nav]');if(navElement){return nav(navElement.dataset.nav)}let edit=target.closest('[data-edit]');if(edit)return openForm(edit.dataset.edit,edit.dataset.id);let del=target.closest('[data-delete]');if(del)return deleteRecord(del.dataset.delete,del.dataset.id);let el=target.closest('[data-act]');if(el){if(el.dataset.act==='close-modal'&&el.classList.contains('modal-shade')&&e.target.closest('.modal'))return;if(el.dataset.act==='close-search'&&el.classList.contains('search-shade')&&e.target.closest('.search-modal'))return;if(el.matches('select[data-act]'))return;return execute(el.dataset.act,el)}});
 document.addEventListener('input',e=>{if(e.target.id==='doc-editor')scheduleDoc();if(e.target.matches('[data-live-filter]'))updateFilteredList(e.target);if(e.target.id==='form-word'){clearTimeout(state.dictionaryTimer);const word=e.target.value.trim();state.dictionaryTimer=setTimeout(async()=>{if(!/^[a-z][a-z -]{0,60}$/i.test(word))return;const meaning=document.querySelector('#form-meaning'),example=document.querySelector('#form-example');if(!meaning||!example)return;const hint=document.querySelector('#dictionary-hint');if(hint)hint.textContent='Anlam ve örnekler aranıyor…';try{const d=await api('dictionary?word='+encodeURIComponent(word));if(document.querySelector('#form-word')?.value.trim()!==word)return;if(d.meanings?.length)meaning.value=d.meanings.join('\n');if(d.examples?.length)example.value=d.examples.join('\n');if(hint)hint.textContent=d.examples?.length>=3?'Anlamlar ve örnekler dolduruldu. İstersen düzenleyebilirsin.':'Bulunan kaynak örnekleri dolduruldu; eksik örnekleri kendin ekleyebilirsin.'}catch{if(hint)hint.textContent='Sözlük bağlantısı kurulamadı; alanları elle doldurabilirsin.'}},450)}});
 document.addEventListener('change',e=>{if(e.target.matches('select[data-act]'))execute(e.target.dataset.act,e.target)});
 $('#sidebar-toggle').addEventListener('click',async()=>{if(innerWidth<=860){document.body.classList.remove('mobile-open');return}const collapsed=!document.body.classList.contains('sidebar-collapsed');document.body.classList.toggle('sidebar-collapsed',collapsed);$('#sidebar-toggle').setAttribute('aria-label',collapsed?'Menüyü genişlet':'Menüyü daralt');$('#sidebar-toggle').title=collapsed?'Menüyü genişlet':'Menüyü daralt';try{await api('settings','POST',{sidebar_collapsed:String(collapsed)})}catch(e){toast('Menü tercihi kaydedilemedi',true)}});
 $('#mobile-menu').addEventListener('click',()=>document.body.classList.add('mobile-open'));$('#sidebar-backdrop').addEventListener('click',()=>document.body.classList.remove('mobile-open'));let sx=0,sy=0,gestureArmed=false,dragging=false,drawerWasOpen=false;document.addEventListener('touchstart',e=>{let t=e.touches[0];sx=t.clientX;sy=t.clientY;drawerWasOpen=document.body.classList.contains('mobile-open');gestureArmed=drawerWasOpen||sx<=36;dragging=false},{passive:true});document.addEventListener('touchmove',e=>{if(!gestureArmed)return;let t=e.touches[0],dx=t.clientX-sx,dy=t.clientY-sy;if(Math.abs(dy)>10&&Math.abs(dy)>Math.abs(dx)+6){gestureArmed=false;$('#sidebar').style.transform='';return}const gestureDirection=drawerWasOpen?dx<=-18:dx>=18;if(!dragging&&!gestureDirection)return;dragging=true;let sidebar=$('#sidebar'),width=sidebar.offsetWidth,translate=drawerWasOpen?Math.max(-width,Math.min(0,dx)):Math.max(-width,Math.min(0,dx-width));sidebar.style.transform=`translate3d(${translate}px,0,0)`},{passive:true});document.addEventListener('touchend',e=>{if(!gestureArmed)return;gestureArmed=false;if(!dragging)return;dragging=false;let dx=e.changedTouches[0].clientX-sx;$('#sidebar').style.transform='';if(drawerWasOpen&&dx<-65)document.body.classList.remove('mobile-open');else if(!drawerWasOpen&&dx>65)document.body.classList.add('mobile-open')},{passive:true});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'){closeModal();$('#search-root').replaceChildren();document.body.classList.remove('mobile-open')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&state.nav==='documents'){e.preventDefault();saveDocument()}});
 window.addEventListener('beforeunload',()=>{if($('#doc-editor'))saveDocument()})}
